const $=s=>document.querySelector(s);
const app=$('#app'), nav=$('#nav');
// GitHub Pages shares an origin across repositories: never touch the old app keys.
const PREFIX='yasai-parents-v1-';
const get=(key,fallback)=>{try{return JSON.parse(localStorage.getItem(PREFIX+key))??fallback}catch{return fallback}};
const save=(key,value)=>localStorage.setItem(PREFIX+key,JSON.stringify(value));
const escapeHtml=value=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const vegetableIllustrations={"小松菜":"data:image/webp;base64,","青梗菜":"data:image/webp;base64,","白菜":"data:image/webp;base64,","ほうれん草":"data:image/webp;base64,","カリフラワー":"data:image/webp;base64,","ブロッコリー":"data:image/webp;base64,","かぶ":"data:image/webp;base64,","ごぼう":"data:image/webp;base64,","大根":"data:image/webp;base64,","人参":"data:image/webp;base64,"};
const recipeImages={'小松菜お浸し':'images/recipe_01.jpeg'};
let remoteRecipes=[],remoteNotices=[],remoteLoaded=false,loadError='',contentSource='snapshot';
let page='home',vegSel=null,recipeSel=null,editId=null,returnPage='recipe',flash='';
let historyRecipe='',historyMonth='';
let historyView='list',calendarMonth=localDate().slice(0,7),historyDay='';
let records=get('records',[]),outbox=get('outbox',[]);
let lastChangeVersion=0,profile={email:''};
if(!Array.isArray(records))records=[];
if(!Array.isArray(outbox))outbox=[];
function createEventId(){return 'E-'+(crypto.randomUUID?crypto.randomUUID():Date.now().toString(36)+'-'+Math.random().toString(36).slice(2));}
function getParticipantId(){let id=get('participantId','');if(!id){id='P-'+createEventId();save('participantId',id)}return id;}
function appTitle(){return '朝食やさいチャレンジ';}
function head(title,subtitle=''){return `<div class="top"><div><div class="brand">${escapeHtml(title)}</div><div class="sub">${escapeHtml(subtitle)}</div></div><img class="headerAppIcon" src="icons/icon-192.png" width="48" height="48" alt="" aria-hidden="true"></div>`;}
function remoteById(id){return remoteRecipes.find(r=>String(r.recipe_id)===String(id));}
function remoteByName(name){return remoteRecipes.find(r=>r['料理名']===name);}
function recipeDisplayName(name){return remoteById(recipeIds[name])?.['料理名']||name;}
function localDate(d=new Date()){return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`;}
function applyPublishedData(data){
 if(data?.ok!==true||!Array.isArray(data.recipes)||data.recipes.length===0)return false;
 const ids=new Set(data.recipes.map(r=>r.recipe_id));
 if(!Object.values(recipeIds).every(id=>ids.has(id)))return false;
 remoteRecipes=data.recipes;remoteNotices=Array.isArray(data.notices)?data.notices:[];remoteLoaded=true;return true;
}
async function loadPublishedRecipes(){
 let loaded=false;
 try{
  const url=new URL(window.CONTENT_URL||'./content.json',location.href);url.searchParams.set('_',Date.now());
  const response=await fetch(url,{cache:'no-store'});
  if(!response.ok||!applyPublishedData(await response.json()))throw Error('公開データを確認できません');
  loadError='';loaded=true;contentSource='snapshot';
  if(page!=='recordForm')render();
 }catch(error){}
 if(window.RECIPE_API_URL&&window.PARENTS_API_ENABLED===true){
  try{
   const url=new URL(window.RECIPE_API_URL);url.searchParams.set('_',Date.now());
   const response=await fetch(url,{cache:'no-store',signal:AbortSignal.timeout(15000)});
   const data=await response.json();
   if(!response.ok||data.app!=='parents-v1'||!applyPublishedData(data))throw Error('invalid_api');
   loaded=true;contentSource='live';loadError='';
  }catch(error){if(loaded)loadError='通信できないため、保存済みのレシピを表示しています。';}
 }
 if(!loaded)loadError='レシピ情報を読み込めませんでした。通信状態を確認して再読み込みしてください。';
 if(page!=='recordForm')render();
}
function nutritionFor(veg){return remoteRecipes.find(r=>r['野菜名']===veg&&String(r['栄養学的特徴']||'').trim())?.['栄養学的特徴']||'栄養学的特徴は準備中です。';}
function home(){
 const eaten=records.filter(r=>r.portion>0);
 const together=records.filter(r=>r.participation!=='none');
 app.innerHTML=head(appTitle(),'野菜レシピ')+`<div class="hero"><b>朝ごはんに、やさいをプラス！</b></div>
 <div class="stats"><div class="card"><b>${records.length}</b><span class="note">記録した回数</span></div><div class="card"><b>${new Set(eaten.map(r=>r.recipe_id)).size}</b><span class="note">食べた料理</span></div><div class="card"><b>${together.length}</b><span class="note">調理に参加した回数</span></div></div>
 ${loadError?`<p class="card loadError" role="alert">${escapeHtml(loadError)}</p>`:''}
 <h2>秋冬の野菜レシピ</h2><div class="homeRows">${currentVegetables().map(homeRecipeRow).join('')}</div>`;
}
function homeRecipeRow(v){return `<section class="homeRow"><div class="vegTitle"><img class="vegetableIllustration" style="width:56px;height:56px;object-fit:contain;flex:none" src="${vegetableIllustrations[v[0]]}" alt="" aria-hidden="true"><div class="vegHeadingText"><b>${escapeHtml(v[0])}</b><p class="vegNutrition">${escapeHtml(nutritionFor(v[0]))}</p></div></div><div class="threeRecipes">${v[2].map((name,i)=>{
 const count=records.filter(r=>r.recipe_id===recipeIds[name]).length;
 return `<button class="homeRecipe" onclick="openRecipeHome('${v[0]}',${i})">${recipePhoto(name)?`<img class="recipePhoto" src="${escapeHtml(recipePhoto(name))}" alt="${escapeHtml(recipeDisplayName(name))}" loading="lazy">`:`<div class="photoPlaceholder">${v[1]}</div>`}<b>${escapeHtml(recipeDisplayName(name))}</b><div class="recordCount">${count?`記録 ${count}回`:'記録なし'}</div></button>`;
 }).join('')}</div></section>`;}
function recipe(){
 if(!recipeSel){page='home';home();return;}
 const r=remoteById(recipeSel.recipe_id),name=r?.['料理名']||recipeSel.name;
 app.innerHTML=`<button class="back" onclick="go('home')">‹ ホームにもどる</button>${head(name,recipeSel.veg)}${r?.['調理法']?`<p class="recipeCookingMethod">調理法：${escapeHtml(r['調理法'])}</p>`:''}${recipeEnergyNav()}<div id="recipeSwipeArea">${recipePhoto(recipeSel.name,recipeSel.recipe_id)?`<div class="card recipePhotoCard"><img class="detailRecipePhoto" src="${escapeHtml(recipePhoto(recipeSel.name,recipeSel.recipe_id))}" alt="${escapeHtml(name)}"></div>`:''}<div class="card">${recipeDetailHTML(recipeSel.name,recipeSel.recipe_id)}</div></div><div class="card"><h3>お子さんの様子を記録</h3><p class="note">同じ料理も、そのつど何度でも記録できます。</p><button class="primary" onclick="openRecordForm()">記録を追加</button></div><h2>この料理の記録</h2>${recordList(records.filter(x=>x.recipe_id===recipeSel.recipe_id),'recipe')}`;
}
const PARTICIPATION=[['together','一緒に作った'],['helped','一部を手伝った'],['none','参加していない']];
const PORTIONS=[[1,'全部'],[0.75,'3/4'],[0.5,'半分'],[0.25,'1/4'],[0,'食べなかった']];
function openRecordForm(id=null,from='recipe'){
 editId=id;returnPage=from;
 if(id){const r=records.find(x=>x.id===id);if(!r)return;recipeSel={recipe_id:r.recipe_id,name:r.recipe,veg:r.veg};}
 page='recordForm';render();scrollTo(0,0);
}
function recordForm(){
 const r=records.find(x=>x.id===editId);
 app.innerHTML=`<button class="back" onclick="go('${returnPage}')">‹ もどる</button>${head(editId?'記録を編集':'記録を追加',recipeSel.name)}<form id="recordForm" class="card recordForm"><label for="recordDate">日付</label><input id="recordDate" type="date" required value="${escapeHtml(r?.date||localDate())}"><fieldset><legend>子どもの調理参加</legend>${PARTICIPATION.map(([value,label])=>`<label class="radioChoice"><input type="radio" name="participation" value="${value}" required ${r?.participation===value?'checked':''}>${label}</label>`).join('')}</fieldset><fieldset><legend>子どもの摂取量</legend>${PORTIONS.map(([value,label])=>`<label class="radioChoice"><input type="radio" name="portion" value="${value}" required ${r&&r.portion===value?'checked':''}>${label}</label>`).join('')}</fieldset><p id="formError" class="formError" role="alert"></p><button type="submit" class="primary">${editId?'変更を保存':'記録を保存'}</button><p class="note">記録はこの端末・ブラウザに保存されます。ブラウザのデータを消すと記録も消えます。</p></form>`;
 $('#recordForm').addEventListener('submit',submitRecord);
}
function validRecordDate(date){if(!/^\d{4}-\d{2}-\d{2}$/.test(date))return false;const d=new Date(date+'T12:00:00');return !Number.isNaN(d.getTime())&&localDate(d)===date;}
function persistRecordChange(next,operation,record){
 // Save data and the retry queue together so a failed write never reports success.
 const version=Math.max(Date.now(),lastChangeVersion+1,...outbox.map(e=>(Number(e.change_version||e.ts)||0)+1));
 const nextOutbox=[...outbox,{event_id:createEventId(),record_id:record.id,type:operation,participant_id:getParticipantId(),app_version:window.APP_VERSION,ts:version,change_version:version,...record}];
 try{save('state',{records:next,outbox:nextOutbox,lastChangeVersion:version,profile});}catch(error){throw Error('保存できませんでした。ブラウザの保存容量や設定を確認してください。');}
 records=next;outbox=nextOutbox;lastChangeVersion=version;syncActionLogs();
}
function submitRecord(event){
 event.preventDefault();
 const form=event.currentTarget;
 const date=$('#recordDate').value,participation=form.elements.participation.value,portionText=form.elements.portion.value;
 if(!validRecordDate(date)||!PARTICIPATION.some(x=>x[0]===participation)||portionText===''||!PORTIONS.some(x=>x[0]===Number(portionText))){$('#formError').textContent='日付・調理参加・摂取量を選択してください。';return;}
 const old=records.find(x=>x.id===editId);
 const record={id:old?.id||createEventId(),recipe_id:recipeSel.recipe_id,recipe:recipeSel.name,veg:recipeSel.veg,date,participation,portion:Number(portionText),createdAt:old?.createdAt||Date.now(),updatedAt:Date.now()};
 try{persistRecordChange(old?records.map(x=>x.id===old.id?record:x):[...records,record],old?'record_updated':'record_created',record);}catch(error){$('#formError').textContent=error.message;return;}
 flash=old?'記録を更新しました。':'記録を保存しました。';page=returnPage;editId=null;render();
}
function deleteRecord(id){
 const record=records.find(x=>x.id===id);if(!record)return;
 if(!confirm(`${record.date}「${record.recipe}」の記録を削除しますか？`))return;
 try{persistRecordChange(records.filter(x=>x.id!==id),'record_deleted',record);}catch(error){alert(error.message);return;}
 flash='記録を削除しました。';render();
}
function recordList(list,from='record'){
 if(!list.length)return '<div class="card emptyState">記録はまだありません。レシピ詳細の「記録を追加」から登録できます。</div>';
 return [...list].sort((a,b)=>b.date.localeCompare(a.date)||b.createdAt-a.createdAt).map(r=>`<article class="card historyItem"><p class="note">${escapeHtml(r.date)} ・ ${escapeHtml(r.veg)}</p><h3>${escapeHtml(r.recipe)}</h3><p>調理参加：${PARTICIPATION.find(x=>x[0]===r.participation)?.[1]||'未記録'}<br>摂取量：${PORTIONS.find(x=>x[0]===r.portion)?.[1]||'未記録'}</p><div class="historyActions"><button class="secondary" onclick="openRecordForm('${r.id}','${from}')">編集</button><button class="secondary danger" onclick="deleteRecord('${r.id}')">削除</button></div></article>`).join('');
}
function setHistoryView(view){historyView=view;historyDay='';if(view==='calendar')historyMonth=calendarMonth;record();}
function moveCalendar(delta){const [y,m]=calendarMonth.split('-').map(Number);calendarMonth=localDate(new Date(y,m-1+delta,1)).slice(0,7);historyMonth=calendarMonth;historyDay='';record();}
function historyCalendar(){
 const [y,m]=calendarMonth.split('-').map(Number),first=new Date(y,m-1,1).getDay(),days=new Date(y,m,0).getDate();
 const counts={};records.filter(r=>(!historyRecipe||r.recipe_id===historyRecipe)&&r.date.startsWith(calendarMonth)).forEach(r=>counts[r.date]=(counts[r.date]||0)+1);
 return `<section class="card"><div class="calendarHeading"><button class="secondary" aria-label="前の月" onclick="moveCalendar(-1)">‹</button><h2>${y}年${m}月</h2><button class="secondary" aria-label="次の月" onclick="moveCalendar(1)">›</button></div><p class="note">日付を選ぶと、その日の記録を表示します。</p><div class="recordCalendar">${['日','月','火','水','木','金','土'].map(d=>`<span class="calendarWeekday">${d}</span>`).join('')}${'<span></span>'.repeat(first)}${Array.from({length:days},(_,i)=>{const date=calendarMonth+'-'+String(i+1).padStart(2,'0'),n=counts[date]||0;return `<button class="calendarDay ${historyDay===date?'selected':''} ${date===localDate()?'today':''}" aria-label="${date}、記録${n}件" aria-pressed="${historyDay===date}" onclick="historyDay='${date}';record()"><b>${i+1}</b><span>${n?n+'件':'　'}</span></button>`}).join('')}</div>${historyDay?`<button class="secondary" onclick="historyDay='';record()">この月のすべての記録</button>`:''}</section>`;
}
function record(){
 const filtered=records.filter(r=>(!historyRecipe||r.recipe_id===historyRecipe)&&(!historyMonth||r.date.startsWith(historyMonth)));
 const displayed=historyView==='calendar'&&historyDay?filtered.filter(r=>r.date===historyDay):filtered;
 app.innerHTML=head('記録','お子さんの調理参加と食べた量')+`<div class="historyViewSwitch" role="group" aria-label="記録の表示方法"><button class="secondary" aria-pressed="${historyView==='list'}" onclick="setHistoryView('list')">一覧</button><button class="secondary" aria-pressed="${historyView==='calendar'}" onclick="setHistoryView('calendar')">カレンダー</button></div><div class="card historyFilters"><label for="historyRecipe">料理で絞り込み</label><select id="historyRecipe"><option value="">すべての料理</option>${Object.entries(recipeIds).map(([name,id])=>`<option value="${id}" ${historyRecipe===id?'selected':''}>${escapeHtml(recipeDisplayName(name))}</option>`).join('')}</select><label for="historyMonth">月で絞り込み</label><input id="historyMonth" type="month" value="${escapeHtml(historyMonth)}"><button class="secondary" onclick="historyRecipe='';historyDay='';historyMonth=historyView==='calendar'?calendarMonth:'';record()">絞り込みを解除</button></div>${historyView==='calendar'?historyCalendar():''}<p class="note">${historyView==='calendar'&&historyDay?escapeHtml(historyDay)+'：':''}${displayed.length}件の記録</p>${recordList(displayed)}`;
 $('#historyRecipe').addEventListener('change',e=>{historyRecipe=e.target.value;record()});$('#historyMonth').addEventListener('change',e=>{historyMonth=e.target.value;historyDay='';if(historyView==='calendar'){calendarMonth=historyMonth||localDate().slice(0,7);historyMonth=calendarMonth;}record()});
}
function profileFormHTML(){return `<section class="card"><h2>メールアドレスの登録（任意）</h2><p>アンケートとこの端末の利用記録を照合するために使用します。アンケートにも同じメールアドレスを入力してください。登録しなくても、すべての機能を利用できます。</p><p class="note">ログインや本人確認の機能はありません。別の端末への記録の引き継ぎには使えません。</p><form id="profileForm" class="recordForm"><label for="profileEmail">メールアドレス</label><input id="profileEmail" type="email" autocomplete="email" maxlength="254" required value="${escapeHtml(profile.email)}"><label class="radioChoice"><input type="checkbox" id="profileConsent" required>アンケート照合のため、メールアドレスと利用記録を管理者が管理用シートに保存・利用することに同意します。</label><p id="profileError" class="formError" role="alert"></p><button class="primary" type="submit">${profile.email?'変更して登録':'登録する'}</button>${profile.email?'<button class="secondary" type="button" onclick="removeProfile()">登録を解除</button>':''}</form><p role="status">${outbox.some(e=>e.type.startsWith('profile_'))?'登録情報を送信待ちです。通信後に反映されます。':profile.email?'登録済みです。':''}</p><p class="note">解除すると、この端末の登録メールアドレスを消去し、通信後に管理用シートの登録欄を空にします。すでに照合・転記されたアンケート回答は変更されません。</p></section>`;}
function bindProfileForm(){$('#profileForm')?.addEventListener('submit',submitProfile);}
function saveProfile(email){
 const version=Math.max(Date.now(),lastChangeVersion+1,...outbox.map(e=>(Number(e.change_version||e.ts)||0)+1)),nextProfile={email};
 const event={event_id:createEventId(),participant_id:getParticipantId(),app_version:window.APP_VERSION,type:email?'profile_registered':'profile_removed',email,consent:!!email,change_version:version,ts:version};
 const nextOutbox=[...outbox,event];
 save('state',{records,outbox:nextOutbox,lastChangeVersion:version,profile:nextProfile});
 profile=nextProfile;outbox=nextOutbox;lastChangeVersion=version;render();syncActionLogs();
}
function submitProfile(event){
 event.preventDefault();const email=$('#profileEmail').value.trim().toLowerCase();
 if(!$('#profileConsent').checked||email.length>254||! /^[A-Za-z0-9.!#$%&'*+\/=?^_`{|}~-]+@[A-Za-z0-9](?:[A-Za-z0-9-]*[A-Za-z0-9])?(?:\.[A-Za-z0-9](?:[A-Za-z0-9-]*[A-Za-z0-9])?)+$/.test(email)){$('#profileError').textContent='メールアドレスと同意のチェックを確認してください。';return;}
 try{saveProfile(email);}catch(error){$('#profileError').textContent='保存できませんでした。ブラウザの保存容量や設定を確認してください。';}
}
function removeProfile(){if(!confirm('アンケート照合用のメール登録を解除しますか？'))return;try{saveProfile('');}catch(error){$('#profileError').textContent='解除を保存できませんでした。もう一度お試しください。';}}
const SETTINGS_FAQ=[
 ['アプリの使い方',[
  ['同じ料理を何度も記録できますか？','はい。同じ料理でも、同じ日でも、食べた・作ったつど記録を追加できます。日付、子どもの調理参加、食べた量を選んで保存してください。'],
  ['記録はどこで確認・変更できますか？','下のメニューの「記録」から確認できます。「一覧」と「カレンダー」を切り替えられます。カレンダーの日付を選ぶと、その日の記録が表示されます。各記録の「編集」「削除」から変更できます。'],
  ['食べなかった日も記録できますか？','はい。食べた量で「食べなかった」を選べます。調理に参加したかどうかも、食べた量とは別に記録できます。'],
  ['メールアドレスの登録は必要ですか？','登録は任意です。登録しなくてもレシピの閲覧や記録ができます。登録する場合は、アンケートにも同じメールアドレスを入力してください。管理者がアンケートと利用記録を照合するために使います。'],
  ['メールを登録すれば、別のスマホでも記録を見られますか？','メール登録はアンケート照合用です。ログインや記録の引き継ぎには使えません。記録は、保存した端末の同じブラウザで確認してください。'],
  ['通信できないとき、保存した記録はどうなりますか？','この端末に保存できた記録は、通信できなくても残ります。管理者への送信ができなかったデータは、通信が戻ったときやアプリを開き直したときに再送します。設定画面からも送信待ちのデータを送れます。']
 ]],
 ['野菜と食事について',[
  ['朝ごはんに野菜を取り入れるには？','汁物に加える、前日に用意した野菜のおかずを添えるなど、作りやすい方法から試してみてください。このアプリでは、野菜ごとに3つのレシピを紹介しています。'],
  ['子どもが苦手な野菜は、どうしたらよいですか？','切り方や加熱の仕方、味付けを変えると食べやすくなることがあります。まずは少量を用意し、無理強いせずに試してみてください。洗う・ちぎるなど、調理に関わることも野菜に触れるきっかけになります。'],
  ['野菜の栄養は、どれも同じですか？','野菜によって含まれる栄養素や量は異なります。ホーム画面の野菜名の下に、主な特徴を紹介しています。1種類だけに偏らず、いろいろな野菜を組み合わせる目安にしてください。']
 ]]
];
function faqHTML(){return `<section class="card settingsFAQ"><h2>よくある質問（Q＆A）</h2>${SETTINGS_FAQ.map(([category,items])=>`<h3>${escapeHtml(category)}</h3>${items.map(([question,answer])=>`<details><summary>${escapeHtml(question)}</summary><p>${escapeHtml(answer)}</p></details>`).join('')}`).join('')}</section>`;}
function settings(){app.innerHTML=head('設定')+profileFormHTML()+`<div class="card"><h2>記録の保存について</h2><p>保存した記録は、この端末の同じブラウザで確認できます。</p><p class="note">別の端末への引き継ぎや、消えた記録をアプリに戻す機能はありません。ブラウザのデータを消すと記録を確認できなくなるため、残しておきたい内容は事前に控えてください。</p>${window.ACTION_LOG_API_URL?`<p>利用記録は管理者にも送信されます。送信された記録を、このアプリに読み戻すことはできません。</p><p role="status">${outbox.length?`送信待ちのデータ：${outbox.length}件`:'送信待ちのデータはありません。'}</p>${outbox.length?'<button class="secondary" onclick="syncActionLogs()">未送信のデータを送信</button>':''}`:'<p>現在、利用記録の送信は行っていません。</p>'}</div>`+faqHTML();}
// Recipe browsing remains local. New record events use a dedicated optional endpoint only.
function log(){}
let syncing=false;
async function syncActionLogs(){
 if(syncing||!window.ACTION_LOG_API_URL||!outbox.length||(window.STUDY_MODE===true&&!window.studyCanSync?.()))return;
 syncing=true;
 try{
  while(outbox.length){
   const event=outbox[0];
   const response=await fetch(window.ACTION_LOG_API_URL,{method:'POST',headers:{'Content-Type':'text/plain;charset=utf-8'},body:JSON.stringify({...event,...(window.studyRecordAuth?.(event)||{})}),signal:AbortSignal.timeout(15000)});
   const result=await response.json();
   if(!response.ok||result.ok!==true||result.event_id!==event.event_id)break;
   const next=outbox.filter(x=>x.event_id!==event.event_id);save('state',{records,outbox:next,lastChangeVersion,profile});outbox=next;
  }
 }catch(error){console.warn('記録は端末内に保存されています。連携は次回再試行します。');}finally{syncing=false;if(page==='settings')render();}
}
function go(next){page=next;render();scrollTo(0,0);}
function render(){
 ({home,recipe,record,recordForm,notice,settings}[page]||home)();
 if(flash){const p=document.createElement('p');p.className='saveNotice';p.setAttribute('role','status');p.textContent=flash;app.prepend(p);flash='';}
 if(page==='recipe')setupRecipeSwipe();
 if(page==='settings')bindProfileForm();
 const active=page==='recipe'?'home':page==='recordForm'?(returnPage==='recipe'?'home':'record'):page;
 nav.innerHTML=[['home','⌂','ホーム'],['record','▣','記録'],['notice','🔔','お知らせ'],['settings','⚙','設定']].map(([p,icon,label])=>`<button class="${active===p?'active':''}" onclick="go('${p}')"><b>${icon}</b>${label}</button>`).join('');
}
const savedState=get('state',null);
if(savedState&&Array.isArray(savedState.records)&&Array.isArray(savedState.outbox)){records=savedState.records;outbox=savedState.outbox;lastChangeVersion=Number(savedState.lastChangeVersion)||0;profile=typeof savedState.profile?.email==='string'?savedState.profile:{email:''};}
window.addEventListener('online',syncActionLogs);
render();
loadPublishedRecipes();
syncActionLogs();
if('serviceWorker' in navigator){navigator.serviceWorker.register('./sw.js',{scope:'./'}).catch(()=>{});}
